   CREATE SEQUENCE  "THE"."FOREST_CLIENT_AUDIT_SEQ"  MINVALUE 1 MAXVALUE 999999999999999999999999999 INCREMENT BY 1 START WITH 515452 NOCACHE  NOORDER  NOCYCLE  NOKEEP  NOSCALE  GLOBAL ;

  CREATE TABLE "THE"."FOREST_CLIENT" 
   (	"CLIENT_NUMBER" VARCHAR2(8) NOT NULL ENABLE, 
	"CLIENT_NAME" VARCHAR2(60) NOT NULL ENABLE, 
	"LEGAL_FIRST_NAME" VARCHAR2(30), 
	"LEGAL_MIDDLE_NAME" VARCHAR2(30), 
	"CLIENT_STATUS_CODE" VARCHAR2(3) NOT NULL ENABLE, 
	"CLIENT_TYPE_CODE" VARCHAR2(1) NOT NULL ENABLE, 
	"BIRTHDATE" DATE, 
	"CLIENT_ID_TYPE_CODE" VARCHAR2(4), 
	"CLIENT_IDENTIFICATION" VARCHAR2(40), 
	"REGISTRY_COMPANY_TYPE_CODE" VARCHAR2(4), 
	"CORP_REGN_NMBR" VARCHAR2(9), 
	"CLIENT_ACRONYM" VARCHAR2(8), 
	"WCB_FIRM_NUMBER" VARCHAR2(6), 
	"OCG_SUPPLIER_NMBR" VARCHAR2(10), 
	"CLIENT_COMMENT" VARCHAR2(4000), 
	"ADD_TIMESTAMP" DATE NOT NULL ENABLE, 
	"ADD_USERID" VARCHAR2(30) NOT NULL ENABLE, 
	"ADD_ORG_UNIT" NUMBER(10,0) NOT NULL ENABLE, 
	"UPDATE_TIMESTAMP" DATE NOT NULL ENABLE, 
	"UPDATE_USERID" VARCHAR2(30) NOT NULL ENABLE, 
	"UPDATE_ORG_UNIT" NUMBER(10,0) NOT NULL ENABLE, 
	"REVISION_COUNT" NUMBER(5,0) NOT NULL ENABLE, 
	 CONSTRAINT "FOREST_CLIENT_PK" PRIMARY KEY ("CLIENT_NUMBER")
  USING INDEX  ENABLE, 
	 CONSTRAINT "FC_OU_FK" FOREIGN KEY ("ADD_ORG_UNIT")
