	  REFERENCES "THE"."CLIENT_ID_TYPE_CODE" ("CLIENT_ID_TYPE_CODE") ENABLE, 
	 CONSTRAINT "FC_CSC_FK" FOREIGN KEY ("CLIENT_STATUS_CODE")
	  REFERENCES "THE"."CLIENT_STATUS_CODE" ("CLIENT_STATUS_CODE") ENABLE, 
	 CONSTRAINT "FC_CTCX_FK" FOREIGN KEY ("CLIENT_TYPE_CODE", "REGISTRY_COMPANY_TYPE_CODE")
