  CREATE OR REPLACE FORCE EDITIONABLE VIEW "THE"."V_CLIENT_PUBLIC" ("CLIENT_NUMBER", "CLIENT_NAME", "LEGAL_FIRST_NAME", "LEGAL_MIDDLE_NAME", "CLIENT_STATUS_CODE", "CLIENT_TYPE_CODE") AS 
  SELECT client_number
       , client_name
       , legal_first_name
