  CREATE OR REPLACE FORCE EDITIONABLE VIEW "THE"."GBMS_INVOICE_HISTORY_VW" ("INVOICE_NUMBER", "CANCELLED_BY_INVOICE", "REPLACED_BY_INVOICE", "LEXIS_PERMIT_NUMBER", "INVOICE_AMOUNT", "PRINTED_IND", "PRINTED_DATE", "ENTRY_USERID", "ENTRY_TIMESTAMP", "UPDATE_USERID", "UPDATE_TIMESTAMP") AS 
  select INVOICE_NUMBER, cancelled_by_invc CANCELLED_BY_INVOICE, replaced_by_invc REPLACED_BY_INVOICE, ministry_ref_num LEXIS_PERMIT_NUMBER, INVOICE_AMOUNT, PRINTED_IND, invoice_date PRINTED_DATE, ENTRY_USERID, ENTRY_TIMESTAMP, UPDATE_USERID, UPDATE_TIMESTAMP
    from (SELECT F.INVOICE_NUMBER, F.CANCELLED_BY_INVC, F.REPLACED_BY_INVC, G.MINISTRY_REF_NUM, F.INVOICE_AMOUNT, 'Y' PRINTED_IND, F.INVOICE_DATE, F.ENTRY_USERID, F.ENTRY_TIMESTAMP, F.UPDATE_USERID, F.UPDATE_TIMESTAMP
            FROM FOREST_INVOICE F
      INNER JOIN GENERAL_INVOICE G
              ON F.INVOICE_NUMBER = G.INVOICE_NUMBER
           WHERE F.INVC_SUB_TYPE_CODE = 'EPT'
           UNION
          SELECT FT.INVOICE_NUMBER, NULL CANCELLED_BY_INVC, NULL REPLACED_BY_INVC, GT.MINISTRY_REF_NUM, FT.INVOICE_AMOUNT, 'N' PRINTED_IND, NULL PRINTED_DATE, FT.ENTRY_USERID, FT.ENTRY_TIMESTAMP, FT.UPDATE_USERID, FT.UPDATE_TIMESTAMP
            FROM FOREST_INVC_TXN FT
      INNER JOIN GNRL_INVC_TXN GT
              ON FT.INVOICE_NUMBER = GT.INVOICE_NUMBER
           WHERE FT.INVC_SUB_TYPE_CODE = 'EPT' and FT.BILLING_STATUS_ST <> 'DSC')
        order by ENTRY_TIMESTAMP desc;

